INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('5faa51eb-e635-4b43-bd47-627c5fa2efcf', '051b209e-9985-44da-a832-ca884783cb98', 5, 'A Obediência à Verdade', NULL, '{"intro": "Negar a realidade \u00e9 a raiz de todo sofrimento ps\u00edquico.", "prayer": "Abrace a sua fragilidade diante do Infinito.", "practice": "Aceite uma verdade dif\u00edcil sobre voc\u00ea hoje.", "reflection": "A liberdade real nasce de submeter-se ao que \u00e9 verdadeiro.", "journal_prompt": "Voc\u00ea prefere a mentira que conforta ou a verdade que cura?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;